import React from "react";
import Logo from "../Logo/Logo";

import "./ImageLinkForm.css";

const ImageLinkForm = ({ onInputChange, onButtonSubmit, isLoading }) => {
  const onKeyDown = (event) => {
    if (event.key === "Enter" && !isLoading) onButtonSubmit();
  };
  return (
    <div>
      <h1 className="title">{"SmartBrain"}</h1>
      <Logo />
      <h3 className="caption">
        Enter an image url with face(s), and magic brain will detect them
      </h3>
      <div className="center">
        <div className="form center pa4 br3 shadow-5">
          <input
            className="f4 pa2 w-70 center"
            type="text"
            aria-label="Image URL"
            placeholder="https://..."
            onChange={onInputChange}
            onKeyDown={onKeyDown}
          />
          <button
            className="w-30 grow f4 link ph3 pv2 dib white bg-light-purple"
            onClick={onButtonSubmit}
            disabled={isLoading}
          >
            {isLoading ? "Detecting…" : "Detect"}
          </button>
        </div>
      </div>
    </div>
  );
};

export default ImageLinkForm;
